-- NeuralMart sample data. Safe to run repeatedly (upserts / ON CONFLICT DO NOTHING).
-- Sample users have a disabled password ("!") so nobody can log in as them.

ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, icon = EXCLUDED.icon, description = EXCLUDED.description,
