ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, tagline = EXCLUDED.tagline, description = EXCLUDED.description,
  category_id = EXCLUDED.category_id, seller_id = EXCLUDED.seller_id, icon_url = EXCLUDED.icon_url,
  price_monthly = EXCLUDED.price_monthly, price_yearly = EXCLUDED.price_yearly, has_free_trial = EXCLUDED.has_free_trial,
  is_featured = EXCLUDED.is_featured, icon_name = EXCLUDED.icon_name, brand_colors = EXCLUDED.brand_colors,
  trial_days = EXCLUDED.trial_days, hours_saved = EXCLUDED.hours_saved, use_cases = EXCLUDED.use_cases,
  integrations = EXCLUDED.integrations;
-- (rating_avg / rating_count are left alone on re-runs so real reviews are not overwritten)

ON CONFLICT (app_id, order_index) DO UPDATE SET feature_text = EXCLUDED.feature_text;

ON CONFLICT (app_id, order_index) DO UPDATE SET image_url = EXCLUDED.image_url;

ON CONFLICT (app_id, user_id) DO NOTHING;

ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, price = EXCLUDED.price,
  savings_percent = EXCLUDED.savings_percent, icon_name = EXCLUDED.icon_name, brand_colors = EXCLUDED.brand_colors;

ON CONFLICT (bundle_id, app_id) DO NOTHING;

ON CONFLICT (code) DO UPDATE SET percent_off = EXCLUDED.percent_off, active = EXCLUDED.active;
